"use client";

import { LedType } from "@/types/led";

interface LedPreviewProps {
  left1Label: LedType;
  left2Label: LedType;
  left3Label: LedType;
  right1Label: LedType;
  right2Label: LedType;
  right3Label: LedType;
}

function LedPosition({
  position,
  label,
  align = "left",
}: {
  position: string;
  label: LedType;
  align?: "left" | "right";
}) {
  if (align === "right") {
    return (
      <div className="flex items-center justify-between rounded-md border border-zinc-800 bg-zinc-900 px-3 py-2">
        {/* LED */}
        <div className="h-3 w-3 rounded-full border-2 border-zinc-500 bg-zinc-700" />

        {/* Label */}
        <div className="text-right">
          <p className="text-sm font-semibold text-white">{label}</p>
          <p className="text-[11px] text-zinc-500">{position}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center justify-between rounded-md border border-zinc-800 bg-zinc-900 px-3 py-2">
      {/* Label */}
      <div>
        <p className="text-sm font-semibold text-white">{label}</p>
        <p className="text-[11px] text-zinc-500">{position}</p>
      </div>

      {/* LED */}
      <div className="h-3 w-3 rounded-full border-2 border-zinc-500 bg-zinc-700" />
    </div>
  );
}

export default function LedPreview({
  left1Label,
  left2Label,
  left3Label,
  right1Label,
  right2Label,
  right3Label,
}: LedPreviewProps) {
  return (
    <div>
      <h4 className="mb-3 text-sm font-medium text-zinc-300">
       LED Preview
      </h4>

      <div className="rounded-xl border border-zinc-800 bg-zinc-950 p-5">
        <div className="mb-4 grid grid-cols-2 text-center text-xs font-semibold uppercase tracking-wider text-zinc-500">
          <span>Left Side</span>
          <span>Right Side</span>
        </div>

        <div className="grid grid-cols-2 gap-4">
          {/* LEFT SIDE */}
          <div className="space-y-2">
            <LedPosition position="L1" label={left1Label} />
            <LedPosition position="L2" label={left2Label} />
            <LedPosition position="L3" label={left3Label} />
          </div>

          {/* RIGHT SIDE */}
          <div className="space-y-2">
            <LedPosition
              position="R1"
              label={right1Label}
              align="right"
            />
            <LedPosition
              position="R2"
              label={right2Label}
              align="right"
            />
            <LedPosition
              position="R3"
              label={right3Label}
              align="right"
            />
          </div>
        </div>

        <div className="mt-5 border-t border-zinc-800 pt-3 text-center">
          <p className="text-xs text-zinc-500">
            Reference layout of the media converter front panel.
          </p>
        </div>
      </div>
    </div>
  );
}