"use client";

import { Trash2, Cpu } from "lucide-react";
import { Input } from "@/components/ui/input";
import LedMapping, { LedMappingData } from "./ledMapping";
import { Network } from "lucide-react";

interface MediaConverter {
  mediaConverterId: string;
  left1Label: any;
  left2Label: any;
  left3Label: any;
  right1Label: any;
  right2Label: any;
  right3Label: any;
}

interface Props {
  index: number;
  converter: MediaConverter;
  onIdChange: (id: string) => void;
  onMappingChange: (mapping: LedMappingData) => void;
  onRemove: () => void;
  removable: boolean;
}

export default function MediaConverterCard({
  index,
  converter,
  onIdChange,
  onMappingChange,
  onRemove,
  removable,
}: Props) {
  return (
    <div className="rounded-xl border border-zinc-700 bg-white-300 p-6 shadow-md transition-colors hover:border-zinc-600">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
       <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br from-sky-500 to-blue-600 shadow-lg shadow-blue-500/30">
  <Network className="h-6 w-6 text-white" />
</div>

          <div>
            <h3 className="text-lg font-semibold text-white">
              Media Converter {index + 1}
            </h3>
            
          </div>
        </div>

        {removable && (
          <button
            type="button"
            onClick={onRemove}
            className="rounded-lg p-2 text-zinc-500 transition-colors hover:bg-red-500/10 hover:text-red-400"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* Media Converter ID */}
      <div className="mt-6">
        <label className="mb-2 block text-sm font-medium text-zinc-300">
          Media Converter ID
        </label>

        <Input
          value={converter.mediaConverterId}
          placeholder="MC-001"
          onChange={(e) => onIdChange(e.target.value)}
          className="border-zinc-600 bg-zinc-900 text-white placeholder:text-zinc-500 focus:border-red-500"
        />
      </div>

      {/* Mapping */}
      <div className="mt-6">
        <LedMapping
          value={{
            left1Label: converter.left1Label,
            left2Label: converter.left2Label,
            left3Label: converter.left3Label,
            right1Label: converter.right1Label,
            right2Label: converter.right2Label,
            right3Label: converter.right3Label,
          }}
          onChange={onMappingChange}
        />
      </div>
    </div>
  );
}